/* 增补原型共享投影：账本只写一次；窗口、后台、订单读取同一份结果。不是业务接口。 */
(() => {
  const model=window.SupplementRepaymentModel,base=window.SupplementTemporaryOrders;
  const localStamp=value=>{const d=new Date(value),p=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}`};
  const orders=()=>model.apply(base,model.readLedger());
  const backendOrders=()=>orders().map(r=>({key:r.id,orderNo:r.id,customerName:r.customer,orderTime:r.created,owner:r.owner,cashier:r.cashier,orderAmount:r.amount/100,refundAmount:r.refunded/100,receivable:(r.amount-r.refunded)/100,repaymentStatus:r.state==='migrated'?'-':r.state==='paid'?'已回款':'未回款',afterSaleNos:r.refunded?[`LS-${r.id}`]:[],partnerInfo:r.state==='migrated'?{type:r.partnerType,name:r.partner,accountNo:r.accountNo,owner:r.owner,contact:r.contact,phone:r.phone,payType:r.accountType}:undefined,detail:[`散客门票 ${(r.amount/100).toFixed(2)}元`]}));
  function records(){return model.readLedger().receipts.flatMap(r=>{
    const common={type:'临时客户',name:'公共临时客户',fundingMethod:r.fundingMethod,fundingSources:r.fundingSources||[],applicant:r.applicant,owner:r.owners.join('、'),ownerId:'-',payer:r.payer||'-',paymentMethod:r.method,terminalNo:r.terminal,resourceName:r.resource?.name||'-',resourceId:r.resource?.id||'',repaymentTime:r.paidAt,applyTime:localStamp(r.createdAt),finishTime:localStamp(r.completedAt),status:'success',cashier:r.source==='后台'?'-':r.applicant,cashierId:r.source==='后台'?'-':'CASHIER-YND-001',ticketWindow:r.windowName||'-',ticketWindowId:r.source==='后台'?'-':'WINDOW-YND-001',remark:r.note||'-',attachments:[],cashReceived:r.cash===null?null:r.cash/100,change:r.change/100,mismatchConfirmation:r.mismatchConfirmation};
    const main={...common,key:r.id,recordNo:r.id,kind:'account',accountNo:'CPP202608050003',rechargeType:'充值',operation:'充值',accountType:'挂帐',amount:r.amount/100,settleAmount:r.amount/100,totalReceived:r.total/100,surplus:r.income/100,surplusTarget:r.income?'计入其他收入':'-',targetRecordNo:r.incomeId,orders:r.orders.map(o=>o.id),orderTotalAmount:r.orders.reduce((n,o)=>n+base.find(b=>b.id===o.id).amount,0)/100,afterSaleItems:r.orders.filter(o=>base.find(b=>b.id===o.id).refunded>0).map(o=>({afterSaleNo:'LS-'+o.id,amount:base.find(b=>b.id===o.id).refunded/100,orderNo:o.id})),orderItems:r.orders.map(o=>({...o,orderNo:o.id,amount:o.settled/100}))};
    const income=r.income?{...common,key:r.incomeId,recordNo:r.incomeId,kind:'income',accountNo:'-',accountType:'-',operation:'其他收入',rechargeType:'其他收入',amount:r.income/100,owner:'-',sourceRecordNo:r.id,orders:[]}:null;
    return [main,income].filter(Boolean).map(row=>({...row,flow:{key:'flow-'+row.recordNo,type:row.type,name:row.name,accountNo:row.accountNo,operation:row.operation,accountType:row.accountType,amount:row.amount,documentType:'充值记录单号',documentNo:row.recordNo,owner:row.owner,time:row.finishTime,category:row.kind==='income'?'income':'recharge',paymentMethod:row.paymentMethod,terminalNo:row.terminalNo,repaymentStatus:'-',remark:r.source==='后台'?row.remark:`售票员：${r.applicant}，售票窗口：${r.windowName}${r.note?'；'+r.note:''}`}}));
  }).concat(window.SupplementMigration?.records()||[],window.SupplementUnclaimed?.records()||[],window.SupplementLongtermRecharge?.records()||[],window.SupplementImport?.read()||[]);}
  const pending=()=>backendOrders().filter(r=>r.repaymentStatus==='未回款'&&r.receivable>0);
  const balance=()=>-base.filter(r=>r.state==='pending').reduce((sum,r)=>sum+r.amount-r.refunded,0)/100+model.readLedger().accountDelta/100;
  const consumeFlows=()=>orders().filter(r=>base.find(b=>b.id===r.id).state==='pending').flatMap(current=>{const original=base.find(b=>b.id===current.id),r={...original,state:current.state};return [
    {key:'consume-'+r.id,type:'临时客户',name:'公共临时客户',accountNo:r.accountNo,operation:'消费',accountType:'挂帐',amount:-r.amount/100,documentType:'订单号',documentNo:r.id,orderNo:r.id,owner:r.owner,time:r.created,category:'consume',paymentMethod:'挂帐',terminalNo:'-',repaymentStatus:r.state==='paid'?'已回款':'未回款',remark:'-'},
    ...(r.refunded?[{key:'refund-'+r.id,type:'临时客户',name:'公共临时客户',accountNo:r.accountNo,operation:'退款',accountType:'挂帐',amount:r.refunded/100,documentType:'售后单号',documentNo:'LS-'+r.id,orderNo:r.id,owner:r.owner,time:r.created,category:'refund',paymentMethod:'挂帐',terminalNo:'-',repaymentStatus:'-',remark:'回款前退款'}]:[])
  ]}).concat(window.SupplementMigration?.flows()||[]);
  function backendCommit(value,ids){
    const fixture={payments:[{on:true,scenes:['partner'],code:'CASH',name:value.paymentMethod,sortOrder:1}],bindings:{},resources:[],session:{}};
    const form={date:value.repaymentTime,total:String(value.amount),cash:String(value.amount),excess:value.surplusTarget,payer:value.payer,note:value.remark,code:'CASH',signature:model.resourceState(fixture,'CASH').signature};
    return model.commit({baseOrders:base,ids,form,fixture,today:localStamp(new Date()).slice(0,10),operator:'当前操作员工',windowName:'',source:'后台',confirmedMismatch:true});
  }
  window.SupplementRepaymentShared={orders,backendOrders,pending,records,balance,consumeFlows,backendCommit};
  // 复用窗口既有记录、其他收入、按支付日期的报表，不另写第二套金额汇总。
  if(typeof window.records==='function'){
    const previous=window.records;
    window.records=()=>{const old=previous(),added=records(),stamp=r=>!r.repaymentTime||['-','—'].includes(r.repaymentTime)?String(r.finishTime||''):String(r.repaymentTime);return [...added,...old.filter(r=>!added.some(a=>a.recordNo===r.recordNo))].sort((a,b)=>stamp(b).localeCompare(stamp(a))||String(b.finishTime||'').localeCompare(String(a.finishTime||''))||String(b.recordNo||'').localeCompare(String(a.recordNo||'')))};
    const refresh=()=>{if(typeof partners!=='undefined'&&typeof renderPartners==='function'){const core=window.SupplementMigration;for(const p of core.catalog().filter(core.eligible)){let current=partners.find(r=>r.accountNo===p.accountNo);if(!current){current={...p,id:p.key||p.accountNo};partners.push(current)}Object.assign(current,p,{credit:(p.creditAmount||0)-(p.creditMigrationDelta||0)-(p.creditRechargeDelta||0)+core.delta(p.accountNo,'挂帐')+(window.SupplementLongtermRecharge?.delta(p.accountNo,'挂帐')||0),prepay:(p.prepayBalance||0)-(p.prepayMigrationDelta||0)-(p.prepayRechargeDelta||0)+core.delta(p.accountNo,'预付款')+(window.SupplementLongtermRecharge?.delta(p.accountNo,'预付款')||0)})}renderPartners()}window.renderRecords('account');window.renderRecords('income');window.renderReport()};
    ['focus','storage','supplement:repayment'].forEach(name=>window.addEventListener(name,refresh));refresh();
    const previousView=window.viewRecord;
    window.viewRecord=no=>{
      const r=records().find(x=>x.recordNo===no);if(!r||r.unclaimedReceipt||r.longtermRecharge||r.offlineNo)return previousView(no);
      const esc=v=>String(v??'-').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
      const pairs=[['充值记录单号',r.recordNo],['合作类型',r.type],['合作伙伴名称',r.name],['账户号',r.accountNo],['处理操作',r.operation],['账户类型',r.accountType],['金额',r.amount.toFixed(2)+' 元'],['支付时间',r.repaymentTime],['客户／付款人',r.payer],['支付方式',r.paymentMethod],['柜台号／POS编号',r.terminalNo],['申请人',r.applicant],['对接负责人',r.owner],['申请时间',r.applyTime],['完成时间',r.finishTime],['充值状态','充值成功'],['售票员',r.cashier],['售票窗口',r.ticketWindow]];
      const full=(label,html)=>`<div class="repayment-detail-full"><span>${label}：</span><div>${html}</div></div>`;
      document.getElementById('detailGrid').innerHTML=pairs.map(([a,b])=>`<span>${esc(a)}：</span><b>${esc(b)}</b>`).join('')+full('备注说明',((r.remark&&!/^[\s—-]*$/.test(r.remark))?esc(r.remark):'')+(r.fundingSources||[]).map(s=>`<br>来源充值记录：<a href="#" onclick="viewRecord('${esc(s.id)}');return false">${esc(s.id)}</a>　${(s.amount/100).toFixed(2)} 元`).join('')+(r.sourceRecordNo?`<br>来源充值记录：<a href="#" onclick="viewRecord('${esc(r.sourceRecordNo)}');return false">${esc(r.sourceRecordNo)}</a>`:'')||'-')+full('充值相关资料','-')+(r.operation==='调账-往来'?full('调账-往来处理结果',`调整金额：+${r.amount.toFixed(2)} 元；目标合作伙伴：${esc(r.targetPartner)}（${esc(r.targetType)}）<br>关联订单：${r.orders.length} 笔；订单总金额：${r.orderTotalAmount.toFixed(2)} 元<br>`+r.orderItems.map(o=>`<a href="order-detail.html?tempOrder=${encodeURIComponent(o.id)}" target="_blank">${esc(o.id)}</a>　${o.amount.toFixed(2)} 元`).join('<br>')+`<br>关联售后单：${r.afterSaleItems.length} 笔；退款金额：${r.afterSaleRefundAmount.toFixed(2)} 元<br>`+r.afterSaleItems.map(a=>esc(a.afterSaleNo)+'　'+a.amount.toFixed(2)+' 元').join('<br>')+(r.mismatchConfirmation?'<br>同客户确认人：'+esc(r.mismatchConfirmation.operator):'')):r.kind==='account'?full('挂帐回款处理结果',`本次平帐金额：${r.amount.toFixed(2)} 元；关联订单：${r.orders.length} 笔<br>`+r.orderItems.map(o=>`<a href="order-detail.html?tempOrder=${encodeURIComponent(o.id)}" target="_blank">${esc(o.id)}</a>　${o.amount.toFixed(2)} 元`).join('<br>')+(r.mismatchConfirmation?'<br>同一客户确认人：'+esc(r.mismatchConfirmation.operator)+'；确认时间：'+esc(localStamp(r.mismatchConfirmation.at)):'')+(r.targetRecordNo?`<br>其他收入：${r.surplus.toFixed(2)} 元；<a href="#" onclick="viewRecord('${r.targetRecordNo}');return false">${esc(r.targetRecordNo)}</a>`:'')):'');
      document.getElementById('detailMask').classList.add('show');

    };
  }
})();
